// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.IOException;
import java.util.Optional;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * {@link ValueStore} must map every spelling of a language tag to ONE value id, exactly as {@code Literal.equals}
 * (case-insensitive on the tag, RDF 1.1 Concepts 3.3) treats them as one term: cold (after a restart that empties the
 * value-id cache) and warm, for the short-key and the hash lookup paths, for lookups and for the create path.
 */
class ValueStoreLanguageTagIdentityTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	/** Long enough for the encoded literal to exceed the short LMDB key size and take the hash path. */
	private static final String LONG_LABEL = "a label that is far too long for a short LMDB key ".repeat(3);

	private File dataDir;
	private ValueStore valueStore;

	@BeforeEach
	void before(@TempDir File tempDir) throws IOException {
		dataDir = tempDir;
		valueStore = openValueStore();
	}

	@AfterEach
	void after() throws IOException {
		if (valueStore != null) {
			valueStore.close();
		}
	}

	@Test
	void caseVariantResolvesToSameIdWhenCacheIsWarm() throws IOException {
		long id = store(VF.createLiteral("abc", "en"));

		assertEquals(id, valueStore.getId(VF.createLiteral("abc", "EN")), "warm lookup of the case variant");
	}

	@Test
	void caseVariantResolvesToSameIdWhenCacheIsCold() throws IOException {
		long id = store(VF.createLiteral("abc", "en"));
		reopen();

		assertEquals(id, valueStore.getId(VF.createLiteral("abc", "EN")), "cold lookup of the case variant");
		assertEquals(Optional.of("en"), ((Literal) valueStore.getValue(id)).getLanguage(),
				"the stored spelling of the tag is preserved");
	}

	@Test
	void lowercaseSpellingResolvesUppercaseStoredTagWhenCacheIsCold() throws IOException {
		long id = store(VF.createLiteral("abc", "EN"));
		reopen();

		assertEquals(id, valueStore.getId(VF.createLiteral("abc", "en")));
		assertEquals(Optional.of("EN"), ((Literal) valueStore.getValue(id)).getLanguage(),
				"the stored spelling of the tag is preserved");
	}

	@Test
	void longLabelCaseVariantResolvesToSameIdWhenCacheIsCold() throws IOException {
		long id = store(VF.createLiteral(LONG_LABEL, "en-GB"));
		reopen();

		assertEquals(id, valueStore.getId(VF.createLiteral(LONG_LABEL, "EN-gb")), "hash-path lookup of the variant");
		assertEquals(id, valueStore.getId(VF.createLiteral(LONG_LABEL, "en-gb")));
	}

	@Test
	void regionSubtagSpellingsResolveToOneIdAcrossColdLookups() throws IOException {
		long id = store(VF.createLiteral("abc", "en-US"));

		for (String spelling : new String[] { "en-us", "EN-us", "EN-US", "en-Us" }) {
			valueStore.clearCaches();
			assertEquals(id, valueStore.getId(VF.createLiteral("abc", spelling)), "spelling " + spelling);
		}
	}

	@Test
	void creatingCaseVariantAfterRestartReusesTheId() throws IOException {
		long id = store(VF.createLiteral("abc", "en"));
		reopen();

		long variantId = store(VF.createLiteral("abc", "EN"));

		assertEquals(id, variantId, "the case variant is the same term and must not receive a second id");
		assertEquals(Optional.of("en"), ((Literal) valueStore.getValue(id)).getLanguage(),
				"the first written spelling of the tag is kept for the shared term");
	}

	@Test
	void creatingLongLabelCaseVariantAfterRestartReusesTheId() throws IOException {
		long id = store(VF.createLiteral(LONG_LABEL, "en"));
		reopen();

		assertEquals(id, store(VF.createLiteral(LONG_LABEL, "En")), "hash-path create of the case variant");
	}

	@Test
	void batchStoreReusesIdOfCaseVariantAfterRestart() throws IOException {
		long shortId = store(VF.createLiteral("abc", "en"));
		long longId = store(VF.createLiteral(LONG_LABEL, "en"));
		reopen();

		Value[] values = { VF.createLiteral("abc", "EN"), VF.createLiteral(LONG_LABEL, "EN"),
				VF.createLiteral("new", "EN") };
		long[] ids = new long[values.length];
		valueStore.startTransaction(true);
		valueStore.storeValues(values, ids, values.length);
		valueStore.commit();

		assertEquals(shortId, ids[0], "batch store of the short-key case variant");
		assertEquals(longId, ids[1], "batch store of the hash-path case variant");
		assertNotEquals(LmdbValue.UNKNOWN_ID, ids[2]);
		assertNotEquals(shortId, ids[2]);
		assertNotEquals(longId, ids[2]);
		valueStore.clearCaches();
		assertEquals(ids[2], valueStore.getId(VF.createLiteral("new", "en")), "a freshly created variant is one id");
	}

	@Test
	void directionalCaseVariantResolvesToSameIdWhenCacheIsCold() throws IOException {
		long ltrId = store(VF.createLiteral("abc", "en", Literal.BaseDirection.LTR));
		long plainId = store(VF.createLiteral("abc", "en"));
		reopen();

		assertEquals(ltrId, valueStore.getId(VF.createLiteral("abc", "EN", Literal.BaseDirection.LTR)));
		assertEquals(plainId, valueStore.getId(VF.createLiteral("abc", "EN")));
		assertNotEquals(ltrId, plainId, "the base direction is part of the term");
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(VF.createLiteral("abc", "EN", Literal.BaseDirection.RTL)),
				"a different base direction is a different term");
	}

	@Test
	void extendedLengthTagCaseVariantResolvesToSameIdWhenCacheIsCold() throws IOException {
		// a tag longer than 63 bytes uses the extended language-length header of the literal encoding
		String tag = "x-" + "Abcdefgh-".repeat(8) + "End";
		assertTrue(tag.length() > 0x3F);
		long id = store(VF.createLiteral("abc", tag));
		reopen();

		assertEquals(id, valueStore.getId(VF.createLiteral("abc", tag.toUpperCase())));
		assertEquals(id, valueStore.getId(VF.createLiteral("abc", tag.toLowerCase())));
	}

	@Test
	void differentLabelsAndTagsStayDistinct() throws IOException {
		long id = store(VF.createLiteral("abc", "en"));
		reopen();

		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(VF.createLiteral("abd", "en")), "other label");
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(VF.createLiteral("abc", "de")), "other tag");
		assertEquals(LmdbValue.UNKNOWN_ID, valueStore.getId(VF.createLiteral("abc", "en-US")), "longer tag");
		// a short plain xsd:string is inlined into its id, so it can never share the language literal's id
		assertNotEquals(id, valueStore.getId(VF.createLiteral("abc")), "no tag");
		assertNotEquals(LmdbValue.UNKNOWN_ID, id);
	}

	private long store(Literal literal) throws IOException {
		valueStore.startTransaction(true);
		long id = valueStore.storeValue(literal);
		valueStore.commit();
		assertNotEquals(LmdbValue.UNKNOWN_ID, id);
		return id;
	}

	private void reopen() throws IOException {
		valueStore.close();
		valueStore = openValueStore();
	}

	private ValueStore openValueStore() throws IOException {
		return new ValueStore(new File(dataDir, "values"), new LmdbStoreConfig());
	}
}
